#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    int current_floor = 0;               /* elevator starts at floor 0 */
    int target_floor;

    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long val = strtol(argv[i], &endptr, 10);

        /* treat any non‑numeric or out‑of‑range value as invalid */
        if (*endptr != '\0' || val < 0 || val > 9) {
            puts("INVALID_FLOOR");
            continue;
        }
        target_floor = (int)val;

        /* move step by step */
        while (current_floor != target_floor) {
            if (current_floor < target_floor) {
                printf("MOVE_UP %d->%d\n", current_floor, current_floor + 1);
                ++current_floor;
            } else {
                printf("MOVE_DOWN %d->%d\n", current_floor, current_floor - 1);
                --current_floor;
            }
        }

        /* arrived at the requested floor */
        printf("ARRIVE %d\n", current_floor);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }

    printf("FINAL_FLOOR=%d\n", current_floor);
    return 0;
}
